  "commands": [
    {
      "keystrokes": "{\n  \"public_message\": \"I've also been free-riding in rounds 1 and 2, earning 20 each time. But I'm willing to cooperate this round if we can all commit to contributing. Let's aim for a balanced approach where everyone contributes enough to make the pool worthwhile. I propose we all contribute around 10 tokens each.\",\n  \"message\": \"I've also been free-riding in rounds 1 and 2, earning 20 each time. But I'm willing to cooperate this round if we can all commit to contributing. Let's aim for a balanced approach where everyone contributes enough to make the pool worthwhile. I propose we all contribute around 10 tokens each.\",\n  \"private_message\": {\"to\": \"agent_0\", \"content\": \"I'm willing to contribute 10 tokens this round if you and the others also commit. Let's make cooperation work.\"}\n}",
      "duration": 0.5
    }
  ],
